// ============================================================
// HUSTLE CLUB — LLM PROVIDERS
// Every provider-specific detail lives in this one file. Nothing
// else in the codebase knows what an "Anthropic" or a "Mistral" is.
//
// ▸ TO SWITCH PROVIDER: you do not edit this file. Set LLM_PROVIDER
//   and the matching key in .env — see CREDENTIALS.md.
//
// ▸ TO ADD A NEW PROVIDER that speaks the OpenAI chat-completions
//   dialect (most of them do — Mistral, Groq, Together, DeepSeek,
//   Fireworks, OpenRouter, LM Studio, vLLM…): add one entry to the
//   PROVIDERS map below using openAICompatible({...}). Six lines.
//
// ▸ TO USE A PROVIDER THAT ISN'T LISTED without touching any code:
//   set LLM_PROVIDER=custom and LLM_BASE_URL=https://their.api/v1.
//   Anything OpenAI-compatible then works out of the box.
//
// The rest of the app speaks ONE canonical request shape:
//   { model, system, messages: [{ role:'user'|'assistant', content }],
//     max_tokens, temperature }
// and gets back ONE canonical response shape:
//   { text, model, usage }
// Each adapter's job is translating between that and its own wire
// format. That is the whole abstraction.
// ============================================================

// --- OpenAI-compatible adapter factory -----------------------
// Mistral's API is OpenAI-shaped, so this factory covers Mistral and
// most of the field. Differences from provider to provider are small
// enough to express as options rather than new code.

function openAICompatible(config) {
  const {
    id,
    label,
    baseUrl,
    defaultModel,
    envPrefix,
    keysUrl,
    // A handful of providers renamed max_tokens. Override if yours did.
    maxTokensField = 'max_tokens',
    requiresKey = true,
    notes = '',
  } = config;

  return {
    id,
    label,
    envPrefix,
    baseUrl,
    defaultModel,
    keysUrl,
    requiresKey,
    notes,
    dialect: 'openai',

    chatUrl: (base) => `${base}/chat/completions`,
    modelsUrl: (base) => `${base}/models`,

    headers(key) {
      const h = { 'content-type': 'application/json' };
      if (key) h.authorization = `Bearer ${key}`;
      return h;
    },

    // Canonical → OpenAI-style. The system prompt becomes the first
    // message rather than a top-level field; that is the only real
    // structural difference from Anthropic.
    toRequest({ model, system, messages, max_tokens, temperature, reasoning_effort }) {
      const body = {
        model,
        messages: system ? [{ role: 'system', content: system }, ...messages] : messages,
      };
      if (max_tokens != null) body[maxTokensField] = max_tokens;
      if (temperature != null) body.temperature = temperature;
      // Reasoning models only. Mistral accepts:
      // none | minimal | low | medium | high | xhigh | max
      // Sending it to a non-reasoning model is an error, so it is only
      // set when explicitly configured.
      if (reasoning_effort) body.reasoning_effort = reasoning_effort;
      return body;
    },

    fromResponse(json) {
      const choice = (json && json.choices && json.choices[0]) || null;
      const content = choice && choice.message ? choice.message.content : '';
      return {
        // ⚠️ LOAD-BEARING. With reasoning enabled, Mistral returns
        // content as an ARRAY of typed chunks — verified live against
        // mistral-small-2603 with reasoning_effort=high:
        //   [{type:'thinking', thinking:[…]}, {type:'text', text:'…'}]
        // Only the 'text' chunks are kept. The model's internal
        // monologue must never be shown to a 14-year-old: it is not
        // written for them, and it has not been through screenOutput
        // in the form the model reasoned it.
        text: Array.isArray(content)
          ? content.filter((c) => !c.type || c.type === 'text').map((c) => c.text || '').join('')
          : String(content || ''),
        model: (json && json.model) || null,
        // 'length' means the model hit max_tokens and was cut off
        // mid-thought. The caller must not present that as a finished
        // answer — a truncated plan loses its safety and legal sections.
        finishReason: (choice && choice.finish_reason) || null,
        usage: json && json.usage
          ? { input: json.usage.prompt_tokens, output: json.usage.completion_tokens }
          : null,
      };
    },

    listModels(json) {
      const rows = (json && json.data) || [];
      return rows.map((m) => ({ id: m.id, label: m.name || m.id })).filter((m) => m.id);
    },

    // Error bodies vary more than the success shape does. Verified live:
    // Mistral 401 → {"detail":"Unauthorized"}; Mistral validation errors
    // → {"message":{"detail":[{"msg":…}]}}; OpenAI → {"error":{"message":…}}.
    upstreamError(json) {
      const text = (v) => {
        if (!v) return null;
        if (typeof v === 'string') return v;
        if (Array.isArray(v)) return v[0] ? text(v[0].msg || v[0].message || v[0]) : null;
        return text(v.message || v.detail || v.msg);
      };
      if (!json) return null;
      return text(json.error) || text(json.message) || text(json.detail) || null;
    },
  };
}

// --- Anthropic adapter --------------------------------------
// Anthropic uses its own Messages API: a top-level `system` field,
// an `x-api-key` header instead of Bearer auth, a required version
// header, and a `content` array in the response.

const anthropic = {
  id: 'anthropic',
  label: 'Anthropic (Claude)',
  envPrefix: 'ANTHROPIC',
  baseUrl: 'https://api.anthropic.com/v1',
  defaultModel: 'claude-haiku-4-5',
  keysUrl: 'https://console.anthropic.com/settings/keys',
  requiresKey: true,
  dialect: 'anthropic',
  notes: 'The provider Hustle Club shipped with. Still fully supported.',

  chatUrl: (base) => `${base}/messages`,
  modelsUrl: (base) => `${base}/models`,

  headers(key) {
    const h = { 'content-type': 'application/json', 'anthropic-version': '2023-06-01' };
    if (key) h['x-api-key'] = key;
    return h;
  },

  toRequest({ model, system, messages, max_tokens, temperature }) {
    const body = { model, messages, max_tokens: max_tokens ?? 1024 }; // max_tokens is required here
    if (system) body.system = system;
    if (temperature != null) body.temperature = temperature;
    return body;
  },

  fromResponse(json) {
    return {
      text: ((json && json.content) || [])
        .filter((c) => c.type === 'text')
        .map((c) => c.text)
        .join(''),
      model: (json && json.model) || null,
      // Anthropic's equivalent of finish_reason='length'.
      finishReason: json && json.stop_reason === 'max_tokens' ? 'length' : (json && json.stop_reason) || null,
      usage: json && json.usage
        ? { input: json.usage.input_tokens, output: json.usage.output_tokens }
        : null,
    };
  },

  listModels(json) {
    return ((json && json.data) || []).map((m) => ({ id: m.id, label: m.display_name || m.id }));
  },

  upstreamError(json) {
    if (json && json.error && json.error.message) return json.error.message;
    return null;
  },
};

// --- The registry -------------------------------------------
// Default models are sensible starting points, not the only options.
// Run `npm run check` to list every model YOUR key can actually reach,
// then pin one with LLM_MODEL in .env.

const PROVIDERS = {
  mistral: openAICompatible({
    id: 'mistral',
    label: 'Mistral AI',
    envPrefix: 'MISTRAL',
    baseUrl: 'https://api.mistral.ai/v1',
    defaultModel: 'mistral-medium-latest',
    keysUrl: 'https://console.mistral.ai/api-keys',
    notes: 'Hustle Club\'s default. Also try mistral-large-latest (sharper) or mistral-small-latest (cheaper).',
  }),

  openai: openAICompatible({
    id: 'openai',
    label: 'OpenAI',
    envPrefix: 'OPENAI',
    baseUrl: 'https://api.openai.com/v1',
    defaultModel: 'gpt-4o-mini',
    keysUrl: 'https://platform.openai.com/api-keys',
    notes: 'Newer reasoning models want max_completion_tokens — set LLM_MAX_TOKENS_FIELD if you hit that error.',
  }),

  groq: openAICompatible({
    id: 'groq',
    label: 'Groq',
    envPrefix: 'GROQ',
    baseUrl: 'https://api.groq.com/openai/v1',
    defaultModel: 'llama-3.3-70b-versatile',
    keysUrl: 'https://console.groq.com/keys',
    notes: 'Very fast, generous free tier. Good for load-testing the chat flow.',
  }),

  openrouter: openAICompatible({
    id: 'openrouter',
    label: 'OpenRouter',
    envPrefix: 'OPENROUTER',
    baseUrl: 'https://openrouter.ai/api/v1',
    defaultModel: 'openrouter/auto',
    keysUrl: 'https://openrouter.ai/keys',
    notes: 'One key, hundreds of models. Set LLM_MODEL to any id from openrouter.ai/models.',
  }),

  ollama: openAICompatible({
    id: 'ollama',
    label: 'Ollama (self-hosted)',
    envPrefix: 'OLLAMA',
    baseUrl: 'http://localhost:11434/v1',
    defaultModel: 'llama3.1',
    requiresKey: false,
    notes: 'Runs on your own machine, no key, no per-token cost. In Docker use http://host.docker.internal:11434/v1.',
  }),

  anthropic,
};

/** Every provider id, for error messages and the status endpoint. */
export const PROVIDER_IDS = Object.keys(PROVIDERS);

/**
 * Get a provider adapter by id.
 *
 * `custom` is built on demand from LLM_BASE_URL so that an unlisted
 * OpenAI-compatible endpoint needs no code change at all.
 */
export function getProvider(id, settings = {}) {
  const key = String(id || '').toLowerCase().trim();

  if (key === 'custom') {
    const baseUrl = settings.baseUrl;
    if (!baseUrl) {
      throw new Error('LLM_PROVIDER=custom requires LLM_BASE_URL (e.g. https://api.example.com/v1)');
    }
    return openAICompatible({
      id: 'custom',
      label: `Custom endpoint (${baseUrl})`,
      envPrefix: 'LLM',
      baseUrl,
      defaultModel: settings.model || '',
      requiresKey: settings.requiresKey !== false,
      maxTokensField: settings.maxTokensField || 'max_tokens',
      notes: 'Assumed to speak the OpenAI chat-completions dialect.',
    });
  }

  const provider = PROVIDERS[key];
  if (!provider) {
    throw new Error(
      `Unknown LLM_PROVIDER "${id}". Valid values: ${PROVIDER_IDS.join(', ')}, custom.`
    );
  }
  return provider;
}

/** Summary rows for start-up help text and /api/llm/status. */
export function describeProviders() {
  return PROVIDER_IDS.map((id) => {
    const p = PROVIDERS[id];
    return {
      id,
      label: p.label,
      keyEnv: p.requiresKey ? `${p.envPrefix}_API_KEY` : '(no key needed)',
      defaultModel: p.defaultModel,
      keysUrl: p.keysUrl || null,
      notes: p.notes || '',
    };
  });
}
